<?php
require_once '../includes/funcoes.php';exigir_admin();
$rows=$pdo->query("SELECT p.id,p.nome,p.preco,c.nome categoria,COALESCE(SUM(i.quantidade),0) vendidos,COALESCE(SUM(i.quantidade*i.preco_unitario),0) receita FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id LEFT JOIN itens_pedido i ON i.produto_id=p.id LEFT JOIN pedidos pe ON pe.id=i.pedido_id AND pe.status<>'Cancelado' GROUP BY p.id ORDER BY vendidos DESC LIMIT 5")->fetchAll();
$receita=array_sum(array_column($rows,'receita'));$totalVendidos=array_sum(array_column($rows,'vendidos'));$titulo='Produtos estrela';require '../includes/header.php';?>
<div class="admin-shell"><?php require '_menu.php';?><section><div class="section-title"><div class="hero-kicker">Desempenho comercial</div><h1>Dashboard de Performance — Produtos Estrela</h1></div>
<div class="row g-3"><div class="col-lg-7"><div class="panel"><h2 class="h5">Ranking por vendas</h2><p class="muted">Produtos mais vendidos desde o início do registro.</p><?php foreach($rows as $i=>$p):?><div class="rank-row"><div class="rank-letter"><?=chr(65+$i)?></div><div class="flex-grow-1"><strong><?=e($p['nome'])?></strong><div class="muted small"><?=e($p['categoria']??'Sem categoria')?></div><div class="bar-track mt-2"><div class="bar-fill" style="width:<?=$totalVendidos?($p['vendidos']/$totalVendidos*100):0?>%"></div></div></div><strong><?=number_format($p['vendidos'],0,',','.')?></strong></div><?php endforeach;?></div></div>
<div class="col-lg-5"><div class="metric-card mb-3"><div class="metric-label">Receita dos produtos listados</div><div class="metric-value"><?=preco($receita)?></div></div><div class="metric-card mb-3"><div class="metric-label">Unidades vendidas</div><div class="metric-value"><?=$totalVendidos?></div></div><div class="panel"><h2 class="h5">Participação nas vendas</h2><div class="chart-wrap"><canvas id="topChart"></canvas></div></div></div></div></section></div>
<script>new Chart(document.getElementById('topChart'),{type:'doughnut',data:{labels:<?=json_encode(array_column($rows,'nome'))?>,datasets:[{data:<?=json_encode(array_map('intval',array_column($rows,'vendidos')))?>,backgroundColor:['#c77d7d','#d9aaa4','#e8c9c2','#b98f88','#eaded7']}]},options:{responsive:true,maintainAspectRatio:false}});</script>
